<?php
namespace App\Domain\Network\Commerce;
use App\Domain\Network\Commerce\Contracts\PlatformPaymentProvider;use App\Domain\Network\Commerce\Models\{PlatformPaymentAttempt,PlatformPaymentEvent,TenantSaasOrder};use App\Domain\Network\Onboarding\Models\SaasOnboardingApplication;use Illuminate\Http\Request;use Illuminate\Support\Facades\{DB,Log};use Illuminate\Support\Str;use RuntimeException;
final class PlatformPaymentService{public function __construct(private PlatformPaymentProvider$provider,private TenantSaasActivationService$activation){}public function initialize(TenantSaasOrder$o):PlatformPaymentAttempt{$a=DB::transaction(function()use($o){$locked=TenantSaasOrder::whereKey($o->id)->lockForUpdate()->firstOrFail();abort_unless($locked->status==='PENDING_PAYMENT'&&!$locked->expires_at?->isPast(),409);$old=PlatformPaymentAttempt::where('saas_order_id',$locked->id)->whereIn('status',['CREATED','PENDING'])->latest()->first();return$old??PlatformPaymentAttempt::create(['tenant_id'=>$locked->tenant_id,'saas_order_id'=>$locked->id,'provider'=>'MERCADO_PAGO','status'=>'CREATED','external_reference'=>'zs_'.Str::lower(Str::random(48)),'amount'=>$locked->total_amount,'currency'=>$locked->currency]);});if($a->init_point)return$a;$p=$this->provider->createCheckout($a,$o);$url=(string)($p[config('zigo_payments.providers.mercado_pago.environment')==='production'?'init_point':'sandbox_init_point']??$p['init_point']??'');abort_unless(filled($p['id']??null)&&str_starts_with($url,'https://'),502);$a->update(['provider_preference_id'=>$p['id'],'init_point'=>$url,'status'=>'PENDING']);return$a->fresh();}
 public function initializeOnboarding(SaasOnboardingApplication$o):PlatformPaymentAttempt{$a=DB::transaction(function()use($o){$locked=SaasOnboardingApplication::whereKey($o->id)->lockForUpdate()->firstOrFail();abort_unless($locked->status===SaasOnboardingApplication::PENDING_PAYMENT&&$locked->commercial_snapshot_json&&$locked->subdomain_reserved_until?->isFuture(),409);$old=PlatformPaymentAttempt::where('onboarding_application_id',$locked->id)->whereIn('status',['CREATED','PENDING'])->latest()->first();return$old??PlatformPaymentAttempt::create(['onboarding_application_id'=>$locked->id,'provider'=>'MERCADO_PAGO','status'=>'CREATED','external_reference'=>'zo_'.Str::lower(Str::random(48)),'amount'=>$locked->total,'currency'=>$locked->currency]);});if($a->init_point)return$a;$p=$this->provider->createOnboardingCheckout($a,$o);$url=(string)($p[config('zigo_payments.providers.mercado_pago.environment')==='production'?'init_point':'sandbox_init_point']??$p['init_point']??'');abort_unless(filled($p['id']??null)&&$this->safeProviderUrl($url),502);$a->update(['provider_preference_id'=>$p['id'],'init_point'=>$url,'status'=>'PENDING']);return$a->fresh();}
 public function webhook(Request$r):void{$id=(string)$r->query('data.id',$r->input('data.id',''));abort_unless($this->provider->validateWebhook($r,$id),401);$a=PlatformPaymentAttempt::with('order')->where('uuid',(string)$r->query('saas_attempt'))->first();if(!$a)return;$key=(string)$r->header('x-request-id').':'.$id;$e=PlatformPaymentEvent::firstOrCreate(['provider'=>'MERCADO_PAGO','event_key'=>$key],['platform_payment_attempt_id'=>$a->id,'provider_payment_id'=>$id,'status'=>'RECEIVED','received_at'=>now()]);if(!$e->wasRecentlyCreated||$e->status==='PROCESSED')return;try{$p=$this->provider->retrievePayment($id);$this->validate($a,$p);$status=strtolower((string)$p['status']);DB::transaction(function()use($a,$e,$p,$status){$locked=PlatformPaymentAttempt::whereKey($a->id)->lockForUpdate()->firstOrFail();$pid=(string)$p['id'];abort_if(PlatformPaymentAttempt::where('provider_payment_id',$pid)->whereKeyNot($locked->id)->exists(),409);if($status==='approved'){$locked->update(['provider_payment_id'=>$pid,'status'=>'APPROVED','approved_at'=>now()]);$o=TenantSaasOrder::whereKey($locked->saas_order_id)->lockForUpdate()->firstOrFail();if($o->status!=='ACTIVATED'){$o->update(['status'=>'PAID','payment_status'=>'APPROVED','payment_provider'=>'MERCADO_PAGO','payment_reference'=>$pid,'paid_at'=>now()]);$this->activation->activate($o->fresh());}}elseif(in_array($status,['rejected','cancelled','canceled'],true)){$locked->update(['provider_payment_id'=>$pid,'status'=>$status==='rejected'?'REJECTED':'CANCELED','rejected_at'=>now()]);$locked->order()->update(['payment_status'=>$status==='rejected'?'REJECTED':'CANCELED']);}else{$locked->update(['provider_payment_id'=>$pid,'status'=>'PENDING']);}$e->update(['status'=>'PROCESSED','processed_at'=>now()]);});}catch(\Throwable$x){$e->update(['status'=>'INCONSISTENT','error_code'=>Str::limit($x->getMessage(),80,''),'processed_at'=>now()]);Log::warning('SaaS payment rejected',['attempt_uuid'=>$a->uuid,'tenant_id'=>$a->tenant_id,'reason'=>$e->error_code]);}}
 private function validate(PlatformPaymentAttempt$a,array$p):void{if((string)($p['external_reference']??'')!==$a->external_reference)throw new RuntimeException('REFERENCE_MISMATCH');if(bccomp((string)($p['transaction_amount']??''),(string)$a->amount,2)!==0)throw new RuntimeException('AMOUNT_MISMATCH');if((string)($p['currency_id']??'')!==$a->currency)throw new RuntimeException('CURRENCY_MISMATCH');if((string)($p['collector_id']??'')!==$this->provider->accountId())throw new RuntimeException('PLATFORM_ACCOUNT_MISMATCH');}
 private function safeProviderUrl(string$url):bool{$p=parse_url($url);return($p['scheme']??'')==='https'&&preg_match('/(^|\.)mercadopago\.com(\.mx)?$/i',(string)($p['host']??''));}}
